+package main
+
+// AdminForceSignOut invalidates every session held by userID. It follows the
+// same invalidation rule the password reset path established: sessions are
+// keyed by id and carry no per-user index, so every session is scanned once
+// and matching ids are deleted. A user with no sessions is not an error.
+func AdminForceSignOut(store *Store, userID string) error {
+	store.mu.Lock()
+	defer store.mu.Unlock()
+	for id, session := range store.sessions {
+		if session.User == userID {
+			delete(store.sessions, id)
+		}
+	}
+	return nil
+}

