+// startSweeper periodically evicts expired sessions. The interval derives from
+// the same sessionTTL constant passed to NewStore, so the sweep path and the
+// read path share one configured TTL source of truth.
+func startSweeper(store *Store, ttl time.Duration) {
+	interval := ttl / 2
+	if interval <= 0 {
+		return
+	}
+	ticker := time.NewTicker(interval)
+	go func() {
+		for range ticker.C {
+			store.Sweep()
+		}
+	}()
+}
