+// expired reports whether a session last seen at lastSeen is past the
+// configured ttl as of now. It is the single expiry predicate used by all
+// sweep/eviction paths so they share one TTL source of truth.
+func (s *Store) expired(lastSeen time.Time, now time.Time) bool {
+	return now.Sub(lastSeen) > s.ttl
+}
+
+// sweep drops every session whose last-seen time is older than the configured
+// ttl. It returns the number of evicted sessions. Locking is left to the
+// caller, which must hold s.mu for writing.
+func (s *Store) sweep(now time.Time) int {
+	evicted := 0
+	for id, session := range s.sessions {
+		if s.expired(session.LastSeen, now) {
+			delete(s.sessions, id)
+			evicted++
+		}
+	}
+	return evicted
+}
