+func TestDeleteAllForUserIdempotent(t *testing.T) {
+	store := NewStore(time.Minute)
+	store.Create("abc", "ada")
+	store.Create("def", "ada")
+	store.Create("ghi", "grace")
+
+	// Both of ada's sessions go away; grace's session is untouched.
+	if got := store.DeleteAllForUser("ada"); got != 2 {
+		t.Fatalf("DeleteAllForUser(ada) = %d, want 2", got)
+	}
+	if got := store.Len(); got != 1 {
+		t.Fatalf("Len after delete-all = %d, want 1", got)
+	}
+	if _, err := store.Get("ghi"); err != nil {
+		t.Fatalf("Get surviving session: %v", err)
+	}
+
+	// Running it again removes nothing and stays a no-op.
+	if got := store.DeleteAllForUser("ada"); got != 0 {
+		t.Fatalf("repeated DeleteAllForUser(ada) = %d, want 0", got)
+	}
+	if got := store.Len(); got != 1 {
+		t.Fatalf("Len after repeated delete-all = %d, want 1", got)
+	}
+
+	// A user that never existed yields 0, not an error, and no panic.
+	if got := store.DeleteAllForUser("missing"); got != 0 {
+		t.Fatalf("DeleteAllForUser(missing) = %d, want 0", got)
+	}
+
+	// An empty store behaves the same way.
+	empty := NewStore(time.Minute)
+	if got := empty.DeleteAllForUser("ada"); got != 0 {
+		t.Fatalf("DeleteAllForUser on empty store = %d, want 0", got)
+	}
+	if got := empty.Len(); got != 0 {
+		t.Fatalf("Len on empty store = %d, want 0", got)
 	}
 }

