+package main
+
+import (
+	"net/http"
+	"time"
+)
+
+// AdminSessionView is one signed-in user as seen by an administrator. It
+// reuses the JSON tag convention established for Session, plus an Admin flag.
+type AdminSessionView struct {
+	ID       string    `json:"ID"`
+	User     string    `json:"User"`
+	Created  time.Time `json:"Created"`
+	LastSeen time.Time `json:"LastSeen"`
+	Admin    bool      `json:"Admin"`
+}
+
+// adminSessionsHandler reports sessions as admin views. It reads one session
+// when an id query parameter is supplied, otherwise it lists the requested
+// session ids passed as repeated "id" parameters.
+func adminSessionsHandler(store *Store) http.HandlerFunc {
+	return func(w http.ResponseWriter, r *http.Request) {
+		ids := r.URL.Query()["id"]
+		if len(ids) == 0 {
+			writeJSON(w, []AdminSessionView{})
+			return
+		}
+
+		views := make([]AdminSessionView, 0, len(ids))
+		for _, id := range ids {
+			session, err := store.Get(id)
+			if err != nil {
+				http.Error(w, err.Error(), http.StatusNotFound)
+				return
+			}
+			views = append(views, toAdminSessionView(session, false))
+		}
+
+		if len(ids) == 1 {
+			writeJSON(w, views[0])
+			return
+		}
+		writeJSON(w, views)
+	}
+}
+
+// toAdminSessionView converts a stored session into its admin-facing view.
+func toAdminSessionView(session Session, admin bool) AdminSessionView {
+	return AdminSessionView{
+		ID:       session.ID,
+		User:     session.User,
+		Created:  session.Created,
+		LastSeen: session.LastSeen,
+		Admin:    admin,
+	}
+}

