+package main
+
+import (
+	"errors"
+	"testing"
+	"time"
+)
+
+// TestSessionExpiryTable gathers every expiry scenario in one table. Each case
+// drives the store with a controllable clock so no wall-clock sleeping is
+// needed.
+func TestSessionExpiryTable(t *testing.T) {
+	const ttl = time.Minute
+
+	tests := []struct {
+		name  string
+		idle  time.Duration
+		wantErr error
+		wantLen int
+	}{
+		{
+			name:    "fresh session is readable",
+			idle:    0,
+			wantErr: nil,
+			wantLen: 1,
+		},
+		{
+			name:    "exactly ttl is still live",
+			idle:    ttl,
+			wantErr: nil,
+			wantLen: 1,
+		},
+		{
+			name:    "one second past ttl expires",
+			idle:    ttl + time.Second,
+			wantErr: ErrNotFound,
+			wantLen: 0,
+		},
+		{
+			name:    "expired session is dropped",
+			idle:    10 * ttl,
+			wantErr: ErrNotFound,
+			wantLen: 0,
+		},
+	}
+
+	for _, tc := range tests {
+		t.Run(tc.name, func(t *testing.T) {
+			store := NewStore(ttl)
+			clock := time.Now()
+			store.now = func() time.Time { return clock }
+
+			store.Create("abc", "ada")
+			clock = clock.Add(tc.idle)
+
+			session, err := store.Get("abc")
+			if !errors.Is(err, tc.wantErr) {
+				t.Fatalf("Get after %v idle = %v, want %v", tc.idle, err, tc.wantErr)
+			}
+			if tc.wantErr == nil {
+				if session.ID != "abc" || session.User != "ada" {
+					t.Fatalf("session = %+v, want abc/ada", session)
+				}
+			}
+			if got := store.Len(); got != tc.wantLen {
+				t.Fatalf("store length = %d, want %d", got, tc.wantLen)
+			}
+
+			// An expired session must be gone for good: a second read still misses.
+			if tc.wantErr != nil {
+				if _, err := store.Get("abc"); !errors.Is(err, ErrNotFound) {
+					t.Fatalf("second Get = %v, want ErrNotFound", err)
+				}
+			}
+		})
+	}
+}

