+package main
+
+import (
+	"errors"
+	"testing"
+	"time"
+)
+
+func TestSessionExpiryTable(t *testing.T) {
+	const ttl = time.Minute
+
+	tests := []struct {
+		name         string
+		advance      time.Duration
+		wantErr      error
+		wantLenAfter int
+	}{
+		{
+			name:         "fresh session is readable",
+			advance:      0,
+			wantErr:      nil,
+			wantLenAfter: 1,
+		},
+		{
+			name:         "exactly ttl is still live",
+			advance:      ttl,
+			wantErr:      nil,
+			wantLenAfter: 1,
+		},
+		{
+			name:         "one second past ttl is expired",
+			advance:      ttl + time.Second,
+			wantErr:      ErrNotFound,
+			wantLenAfter: 0,
+		},
+		{
+			name:         "expired session is dropped",
+			advance:      2 * ttl,
+			wantErr:      ErrNotFound,
+			wantLenAfter: 0,
+		},
+	}
+
+	for _, tc := range tests {
+		t.Run(tc.name, func(t *testing.T) {
+			store := NewStore(ttl)
+			clock := time.Now()
+			store.now = func() time.Time { return clock }
+			store.Create("abc", "ada")
+
+			clock = clock.Add(tc.advance)
+
+			session, err := store.Get("abc")
+			if !errors.Is(err, tc.wantErr) {
+				t.Fatalf("Get after +%v = %v, want %v", tc.advance, err, tc.wantErr)
+			}
+			if tc.wantErr != nil {
+				if session != (Session{}) {
+					t.Fatalf("expired Get returned session %+v, want zero value", session)
+				}
+			} else {
+				if session.ID != "abc" || session.User != "ada" {
+					t.Fatalf("live Get returned %+v, want abc/ada", session)
+				}
+			}
+			if store.Len() != tc.wantLenAfter {
+				t.Fatalf("store length after Get = %d, want %d", store.Len(), tc.wantLenAfter)
+			}
+		})
+	}
+}

