+package main
+
+import (
+	"runtime"
+	"testing"
+)
+
+// isUnixOS mirrors Go's own `unix` build constraint (cmd/go/internal/syslist).
+func isUnixOS(os string) bool {
+	switch os {
+	case "aix", "android", "darwin", "dragonfly", "freebsd", "hurd", "illumos", "ios", "linux", "netbsd", "openbsd", "solaris":
+		return true
+	}
+	return false
+}
+
+// TestPlatformNoteMatchesBuildTag asserts that platformNote reports "unix" on
+// unix-like targets and "other" everywhere else, i.e. the value agrees with
+// whichever build-tagged file (session_unix.go or session_other.go) the
+// compiler selected for the current GOOS.
+func TestPlatformNoteMatchesBuildTag(t *testing.T) {
+	want := "other"
+	if isUnixOS(runtime.GOOS) {
+		want = "unix"
+	}
+
+	if got := platformNote(); got != want {
+		t.Fatalf("platformNote() = %q on GOOS=%q, want %q", got, runtime.GOOS, want)
+	}
+}
+
+// TestPlatformNoteReturnsNonEmpty guards against a stub that returns an empty
+// string, which would make the platform identifier useless to callers.
+func TestPlatformNoteReturnsNonEmpty(t *testing.T) {
+	if got := platformNote(); got == "" {
+		t.Fatal("platformNote() returned an empty string")
+	}
+}
+
+// TestPlatformNoteStable ensures repeated calls agree, i.e. the function is a
+// pure accessor and does not read mutable state.
+func TestPlatformNoteStable(t *testing.T) {
+	first := platformNote()
+	for i := 0; i < 5; i++ {
+		if got := platformNote(); got != first {
+			t.Fatalf("platformNote() call %d = %q, first call = %q", i+2, got, first)
+		}
+	}
+}
+
+// TestIsUnixOS pins the helper's classification for representative targets so a
+// future edit cannot silently invert the expectation used above.
+func TestIsUnixOS(t *testing.T) {
+	tests := []struct {
+		os   string
+		want bool
+	}{
+		{"linux", true},
+		{"darwin", true},
+		{"freebsd", true},
+		{"openbsd", true},
+		{"windows", false},
+		{"js", false},
+		{"wasip1", false},
+		{"plan9", false},
+	}
+	for _, tc := range tests {
+		if got := isUnixOS(tc.os); got != tc.want {
+			t.Errorf("isUnixOS(%q) = %v, want %v", tc.os, got, tc.want)
+		}
+	}
+}
