+package main
+
+import (
+	"runtime"
+	"testing"
+)
+
+// TestPlatformNoteMatchesBuildTag asserts that the build-tagged
+// platformNote implementation selected for the current target returns the
+// value that matches the tag in effect: "unix" on unix targets and "other"
+// elsewhere. This fails if the build tags on the two files are swapped,
+// missing, or if the returned literals are wrong.
+func TestPlatformNoteMatchesBuildTag(t *testing.T) {
+	got := platformNote()
+
+	if runtime.GOOS == "windows" || runtime.GOOS == "plan9" || runtime.GOOS == "js" || runtime.GOOS == "wasip1" {
+		if got != "other" {
+			t.Fatalf("platformNote() on %s = %q, want %q", runtime.GOOS, got, "other")
+		}
+		return
+	}
+
+	if got != "unix" {
+		t.Fatalf("platformNote() on %s = %q, want %q", runtime.GOOS, got, "unix")
+	}
+}
+
+// TestPlatformNoteIsStable asserts the value is deterministic across repeated
+// calls, so the function is a pure literal return rather than state-derived.
+func TestPlatformNoteIsStable(t *testing.T) {
+	first := platformNote()
+	for i := 0; i < 10; i++ {
+		if got := platformNote(); got != first {
+			t.Fatalf("platformNote() call %d = %q, want stable value %q", i, got, first)
+		}
+	}
+}
+
+// TestPlatformNoteIsKnownLiteral asserts the result is one of the two literals
+// defined by the build-tagged files, catching a regression that returns an
+// empty or unexpected string.
+func TestPlatformNoteIsKnownLiteral(t *testing.T) {
+	switch got := platformNote(); got {
+	case "unix", "other":
+	default:
+		t.Fatalf("platformNote() = %q, want one of \"unix\" or \"other\"", got)
+	}
+}
