+// Peek returns a live session without refreshing its last-seen time. An
+// expired session is dropped and reported as missing. Ids that do not satisfy
+// ValidSessionID are reported as ErrInvalidID.
+func (s *Store) Peek(id string) (Session, error) {
+	if !ValidSessionID(id) {
+		return Session{}, ErrInvalidID
+	}
+	s.mu.RLock()
+	defer s.mu.RUnlock()
+	session, ok := s.sessions[id]
+	if !ok {
+		return Session{}, ErrNotFound
+	}
+	if s.now().Sub(session.LastSeen) > s.ttl {
+		return Session{}, ErrNotFound
+	}
+	return session, nil
+}
