@@ -0,0 +1,83 @@
+package main
+
+import (
+	"errors"
+	"testing"
+	"time"
+)
+
+// TestSessionExpiryTable consolidates the expiry behaviour of Store in a single
+// table. Every case drives a controllable store.now clock so the TTL boundary is
+// exercised deterministically.
+func TestSessionExpiryTable(t *testing.T) {
+	const ttl = time.Minute
+
+	tests := []struct {
+		name    string
+		elapsed time.Duration
+		wantErr error
+		wantLen int
+	}{
+		{
+			name:    "fresh session is readable",
+			elapsed: 0,
+			wantErr: nil,
+			wantLen: 1,
+		},
+		{
+			name:    "exactly ttl is still live",
+			elapsed: ttl,
+			wantErr: nil,
+			wantLen: 1,
+		},
+		{
+			name:    "one second past ttl is expired",
+			elapsed: ttl + time.Second,
+			wantErr: ErrNotFound,
+			wantLen: 0,
+		},
+		{
+			name:    "expired session is dropped from the store",
+			elapsed: 2 * ttl,
+			wantErr: ErrNotFound,
+			wantLen: 0,
+		},
+	}
+
+	for _, tc := range tests {
+		t.Run(tc.name, func(t *testing.T) {
+			store := NewStore(ttl)
+			clock := time.Now()
+			store.now = func() time.Time { return clock }
+
+			created := store.Create("abc", "ada")
+			if created.ID != "abc" || created.User != "ada" {
+				t.Fatalf("created session = %+v, want abc/ada", created)
+			}
+			if store.Len() != 1 {
+				t.Fatalf("length after Create = %d, want 1", store.Len())
+			}
+
+			clock = clock.Add(tc.elapsed)
+			got, err := store.Get("abc")
+
+			if tc.wantErr == nil {
+				if err != nil {
+					t.Fatalf("Get after %v = %v, want no error", tc.elapsed, err)
+				}
+				if got.ID != "abc" || got.User != "ada" {
+					t.Fatalf("session after %v = %+v, want abc/ada", tc.elapsed, got)
+				}
+				if !got.LastSeen.Equal(clock) {
+					t.Fatalf("LastSeen after %v = %v, want %v", tc.elapsed, got.LastSeen, clock)
+				}
+			} else if !errors.Is(err, tc.wantErr) {
+				t.Fatalf("Get after %v = %v, want %v", tc.elapsed, err, tc.wantErr)
+			}
+
+			if store.Len() != tc.wantLen {
+				t.Fatalf("length after %v = %d, want %d", tc.elapsed, store.Len(), tc.wantLen)
+			}
+		})
+	}
+}

