+
+// isUnixBuild reports whether this test binary was built for a unix platform,
+// mirroring the //go:build unix constraint used by session_unix.go.
+func isUnixBuild() bool {
+	switch runtime.GOOS {
+	case "aix", "android", "darwin", "dragonfly", "freebsd", "hurd", "illumos", "ios", "linux", "netbsd", "openbsd", "solaris":
+		return true
+	default:
+		return false
+	}
+}
+
+// TestPlatformNoteMatchesBuildConstraint verifies platformNote reports a value
+// consistent with the unix build constraint semantics: unix builds report
+// "unix", every other GOOS reports "other".
+func TestPlatformNoteMatchesBuildConstraint(t *testing.T) {
+	got := platformNote()
+	want := "other"
+	if isUnixBuild() {
+		want = "unix"
+	}
+	if got != want {
+		t.Fatalf("platformNote() on GOOS=%s = %q, want %q", runtime.GOOS, got, want)
+	}
+}
